/*
 * Activity Details Page
 * Loads activity details from the JSON embedded by Jekyll.
 *
 * Data source: _data/activities.json
 * Example URL: /activities/?id=20261017_cabato_workshop
 */

document.addEventListener("DOMContentLoaded", function () {
    const dataElement = document.getElementById("activities-data");
    const main = document.getElementById("activities-main");
    const errorMessage = document.getElementById("activities-error");

    if (!dataElement || !main || !errorMessage) {
        return;
    }

    let activities;

    // Parse the activity data generated by Jekyll.
    try {
        activities = JSON.parse(dataElement.textContent);
    } catch (error) {
        console.error("Could not parse activity data:", error);

        showError(
            "Activity details could not be loaded because the activity data is invalid."
        );

        return;
    }

    if (!Array.isArray(activities)) {
        showError(
            "Activity details could not be loaded because the activity data has an unexpected format."
        );

        return;
    }

    // Identify the activity using the URL query parameter.
    const params = new URLSearchParams(window.location.search);
    const slug = params.get("id");

    const activity = activities.find(function (item) {
        return item && item.slug === slug;
    });

    if (!activity) {
        showError(
            "The requested activity could not be found. Please check the link or return to the CIVI website."
        );

        return;
    }

    errorMessage.hidden = true;
    main.hidden = false;

    /*
     * Display an error message and hide the activity details.
     */
    function showError(message) {
        main.hidden = true;
        errorMessage.hidden = false;
        errorMessage.textContent = message;
    }

    /*
     * Populate an element with plain text.
     */
    function setText(id, value) {
        const element = document.getElementById(id);

        if (element) {
            element.textContent =
                value === null || value === undefined
                    ? ""
                    : String(value);
        }
    }

    /*
     * Populate a list from an array.
     *
     * Entries formatted as:
     * "PyTorch installation: https://pytorch.org/get-started/locally/"
     *
     * will display the URL as a clickable link.
     */
    function populateList(id, items) {
        const list = document.getElementById(id);

        if (!list) {
            return;
        }

        list.replaceChildren();

        const entries = Array.isArray(items) ? items : [];

        entries.forEach(function (item) {
            const li = document.createElement("li");
            const text = String(
                item === null || item === undefined ? "" : item
            );

            const match = text.match(
                /^(.*?):\s*(https?:\/\/\S+)$/
            );

            if (match) {
                li.appendChild(
                    document.createTextNode(match[1] + ": ")
                );

                const link = document.createElement("a");

                link.href = match[2];
                link.textContent = match[2];
                link.target = "_blank";
                link.rel = "noopener noreferrer";

                li.appendChild(link);
            } else {
                li.textContent = text;
            }

            list.appendChild(li);
        });

        // Hide the section if it has no entries.
        const section = list.closest(".activities-section");

        if (section) {
            section.hidden = list.children.length === 0;
        }
    }

    /*
     * Populate activity details.
     *
     * Expected JSON fields include:
     * type, title, date, presenter_type, presenter, abstract,
     * outline, prerequisites, dependencies, installation_text,
     * speaker_bio, presenter_bio, and youtube_id.
     */
    setText("activity-type", activity.type);
    setText("activity-title", activity.title);
    setText("presenter-type", activity.presenter_type);
    setText("presenter-name", activity.presenter);
    setText("activity-date", activity.date);
    setText("activity-abstract", activity.abstract);

    // Support either field name for the presenter's biography.
    const presenterBio =
        activity.speaker_bio || activity.presenter_bio || "";

    setText("activity-presenter-bio", presenterBio);

    // Update the browser tab title.
    document.title =
        (activity.title || "Activity Details") + " | DLSU-CIVI";

    /*
     * Style the activity type.
     * Workshop activities receive a distinct eyebrow style.
     */
    const eyebrow = document.getElementById("activity-type");

    if (eyebrow) {
        eyebrow.classList.toggle(
            "activities-eyebrow--workshop",
            String(activity.type || "")
                .toLowerCase()
                .includes("workshop")
        );
    }

    /*
     * Embed the YouTube video.
     */
    const videoContainer =
        document.getElementById("activity-video");

    if (videoContainer) {
        videoContainer.replaceChildren();

        if (activity.youtube_id) {
            const iframe = document.createElement("iframe");

            iframe.src =
                "https://www.youtube-nocookie.com/embed/" +
                encodeURIComponent(activity.youtube_id);

            iframe.title =
                activity.title || "Activity video";

            iframe.loading = "lazy";

            iframe.allow =
                "accelerometer; autoplay; clipboard-write; " +
                "encrypted-media; gyroscope; picture-in-picture; web-share";

            iframe.allowFullscreen = true;

            iframe.referrerPolicy =
                "strict-origin-when-cross-origin";

            videoContainer.appendChild(iframe);
            videoContainer.hidden = false;
        } else {
            videoContainer.hidden = true;
        }
    }

    /*
     * Populate activity lists.
     */
    populateList("activity-outline", activity.outline);

    populateList(
        "activity-prerequisites",
        activity.prerequisites
    );

    populateList(
        "activity-dependencies",
        activity.dependencies
    );

    populateList(
        "activity-installation",
        activity.installation_text
    );

    /*
     * Hide optional text sections when their data is empty.
     */
    const abstractSection = document.getElementById(
        "activity-abstract-section"
    );

    if (abstractSection) {
        abstractSection.hidden =
            !String(activity.abstract || "").trim();
    }

    const bioSection = document.getElementById(
        "activity-presenter-bio-section"
    );

    if (bioSection) {
        bioSection.hidden = !String(presenterBio).trim();
    }

    /*
     * Remove the activity currently being viewed from the
     * recent-activities sidebar.
     */
    document
        .querySelectorAll(
            "#recent-activities .recent-activities-card-link"
        )
        .forEach(function (link) {
            const linkUrl = new URL(
                link.href,
                window.location.origin
            );

            if (linkUrl.searchParams.get("id") === slug) {
                const card = link.closest(
                    ".recent-activities-card"
                );

                if (card) {
                    card.remove();
                }
            }
        });
});
